// Este middleware só roda quando alguém chamou next(erro).
app.use((erro, req, res, next) => {
  console.error('a linha quebrou:', erro.message); // detalhe no servidor
  res.status(500).json({ mensagem: 'erro interno' }); // resposta genérica
});

// Rota que detecta um problema e DESVIA a peça para a esteira de reparo:
app.get('/contas/:id', (req, res, next) => {
  const conta = contas.find((c) => c.id === req.params.id);
  if (!conta) {
    return next(new Error('conta não encontrada')); // next COM argumento = desvio
  }
  res.json(conta);
});

// Middleware assíncrono: espera a busca, depois libera a peça.
app.use(async (req, res, next) => {
  try {
    req.usuario = await buscarUsuario(req.headers.token);
    next(); // a estação terminou; a peça segue
  } catch (erro) {
    next(erro); // a busca falhou; peça vai para o reparo
  }
});

// Fábrica de middleware: uma função que devolve um middleware pronto.
function exigirCampo(campo) {
  return (req, res, next) => {
    if (req.body?.[campo] === undefined) {
      return res.status(400).json({ erros: [campo + ' é obrigatório'] });
    }
    next();
  };
}

// A mesma estação com configurações diferentes, em sequência:
app.post('/api/produtos', exigirCampo('nome'), exigirCampo('preco'), (req, res) => {
  res.status(201).json({ criado: true });
});

import express from 'express';

const app = express();
app.use(express.json());

// 1. Estação 1: registra todo pedido que passa.
app.use((req, res, next) => {
  console.log('pedido:', req.method, req.url);
  next();
});

// 2. Fábrica: devolve uma estação que exige um campo no body.
function exigirCampo(campo) {
  return (req, res, next) => {
    if (req.body?.[campo] === undefined || req.body[campo].trim() === '') {
      // 3. Problema do cliente: recusa na hora, sem desviar para o reparo.
      return res.status(400).json({ erros: [campo + ' é obrigatório'] });
    }
    next();
  };
}

// 4. Estação async: espera a busca do usuário antes de liberar.
app.use(async (req, res, next) => {
  try {
    // Busca simulada: na vida real, viria do banco.
    req.usuario = await Promise.resolve({ id: 1, nome: 'Ana' });
    next();
  } catch (erro) {
    next(erro); // falha na estação → esteira de reparo
  }
});

// 5. A rota final: recebe a peça pronta pelas estações anteriores.
app.post('/api/mensagens', exigirCampo('texto'), (req, res) => {
  res.status(201).json({ enviadaPor: req.usuario.nome, texto: req.body.texto });
});

// 6. Esteira de reparo: o error middleware — QUATRO argumentos.
app.use((erro, req, res, next) => {
  console.error('a linha quebrou:', erro.message);
  res.status(500).json({ mensagem: 'erro interno' });
});

app.listen(3000);
